                                   tab === "Plan" ? Crown :
                                      tab === "Notifications" ? Bell :
                                         tab === "Integrations" ? Link2 : Server;
                             return (
                                <button
                                   key={tab}
                                   onClick={() => setActiveTab(tab)}
                                   className={`flex w-full items-center justify-between transition-all duration-300 
relative group rounded-xl px-6 py-3 text-[14px] ${activeTab === tab
                                      ? "bg-white/50 dark:bg-white/10 text-slate-900 dark:text-white font-bold 
backdrop-blur-xl shadow-[0_4px_20px_rgba(0,0,0,0.06),inset_0_1px_0_rgba(255,255,255,0.9)] dark:shadow-none border 
