                                      : "text-slate-500 dark:text-slate-400 hover:bg-white/30 dark:hover:bg-white/5 
hover:text-slate-900 dark:hover:text-white border border-transparent"
                                      }`}
                                >
                                   <div className="flex items-center gap-3">
                                      {activeTab === tab && (
                                         <div className={`absolute right-0 top-1/2 -translate-y-1/2 w-1 h-5 
${userSubscription === "advanced" ? "bg-white shadow-[0_0_10px_rgba(255,255,255,0.3)]" : "bg-blue-600 
shadow-[0_0_10px_rgba(37,99,235,0.4)]"} rounded-full`} />
                                      )}
                                      <Icon size={18} className={`transition-colors duration-300 ${activeTab === tab ? 
(userSubscription === "advanced" ? "text-white" : "text-blue-600") : "text-slate-400 group-hover:text-slate-600 
dark:group-hover:text-slate-200"}`} />
                                      <span>{tab}</span>
